import 'dart:convert';

import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:google_fonts/google_fonts.dart';
import 'package:http/http.dart' as http;

/// Invite screen loads the permanent referral code generated by the backend.
class InviteFriendsScreen extends StatefulWidget {
  const InviteFriendsScreen({super.key});

  @override
  State<InviteFriendsScreen> createState() => _InviteFriendsScreenState();
}

class _InviteFriendsScreenState extends State<InviteFriendsScreen> {
  static const String _apiBaseUrl = 'https://aitradex-api.onrender.com/api';

  String _referralCode = '';
  bool _loadingCode = true;
  String? _loadError;

  @override
  void initState() {
    super.initState();
    _loadReferralCode();
  }

  Future<void> _loadReferralCode() async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) {
      if (mounted) {
        setState(() {
          _loadingCode = false;
          _loadError = 'Please sign in to view your referral code.';
        });
      }
      return;
    }

    if (mounted) {
      setState(() {
        _loadingCode = true;
        _loadError = null;
      });
    }

    try {
      final token = await user.getIdToken();
      if (token == null || token.isEmpty) throw Exception('Firebase token unavailable');

      final response = await http.get(
        Uri.parse('$_apiBaseUrl/users/firebase/${Uri.encodeComponent(user.uid)}'),
        headers: {
          'Accept': 'application/json',
          'Authorization': 'Bearer $token',
        },
      ).timeout(const Duration(seconds: 20));

      if (response.statusCode < 200 || response.statusCode >= 300) {
        throw Exception(
          'Unable to load your profile (HTTP ${response.statusCode}). '
              'Please try again. If this continues, sign out and sign in again.',
        );
      }

      final decoded = jsonDecode(response.body);
      if (decoded is! Map<String, dynamic>) {
        throw const FormatException('Unexpected profile response.');
      }

      final dynamic userData = decoded['user'] ?? decoded['data'];
      if (userData is! Map) {
        throw const FormatException('Your profile was not returned by the server.');
      }

      final String code =
      (userData['referralCode'] ?? '').toString().trim().toUpperCase();

      if (code.isEmpty) {
        throw const FormatException(
          'Your referral code is not available yet. Please try again.',
        );
      }

      if (mounted) {
        setState(() {
          _referralCode = code;
          _loadError = null;
        });
      }
    } catch (error) {
      debugPrint('Load referral code error: $error');
      if (mounted) {
        setState(() {
          _loadError = error.toString().replaceFirst('Exception: ', '');
        });
      }
    } finally {
      if (mounted) setState(() => _loadingCode = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final ColorScheme colors = Theme.of(context).colorScheme;
    final bool dark = Theme.of(context).brightness == Brightness.dark;
    final String code = _loadingCode ? 'LOADING...' : (_referralCode.isEmpty ? 'NOT AVAILABLE' : _referralCode);

    return Scaffold(
      backgroundColor: Theme.of(context).scaffoldBackgroundColor,
      appBar: AppBar(
        title: Text('Invite Friends', style: GoogleFonts.poppins(fontWeight: FontWeight.w700, fontSize: 19)),
        centerTitle: false,
        elevation: 0,
      ),
      body: SafeArea(
        child: ListView(
          padding: const EdgeInsets.fromLTRB(20, 8, 20, 28),
          children: [
            Container(
              padding: const EdgeInsets.fromLTRB(22, 24, 22, 22),
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(28),
                gradient: LinearGradient(
                  begin: Alignment.topLeft,
                  end: Alignment.bottomRight,
                  colors: [colors.primary, colors.primary.withValues(alpha: 0.76)],
                ),
                boxShadow: [
                  BoxShadow(color: colors.primary.withValues(alpha: 0.20), blurRadius: 25, offset: const Offset(0, 12)),
                ],
              ),
              child: Column(
                children: [
                  Container(
                    width: 76,
                    height: 76,
                    decoration: BoxDecoration(color: Colors.white.withValues(alpha: 0.17), shape: BoxShape.circle),
                    child: const Icon(Icons.card_giftcard_rounded, color: Colors.white, size: 38),
                  ),
                  const SizedBox(height: 17),
                  Text('Good things are better shared', textAlign: TextAlign.center,
                      style: GoogleFonts.poppins(color: Colors.white, fontSize: 22, height: 1.25, fontWeight: FontWeight.w800)),
                  const SizedBox(height: 8),
                  Text('Invite friends to AiTradeX and earn AiTradeX Coins together.',
                      textAlign: TextAlign.center,
                      style: GoogleFonts.poppins(color: Colors.white.withValues(alpha: 0.88), fontSize: 12, height: 1.55)),
                  const SizedBox(height: 22),
                  Container(
                    width: double.infinity,
                    padding: const EdgeInsets.symmetric(vertical: 17, horizontal: 16),
                    decoration: BoxDecoration(
                      color: Colors.white.withValues(alpha: 0.13),
                      borderRadius: BorderRadius.circular(20),
                      border: Border.all(color: Colors.white.withValues(alpha: 0.22)),
                    ),
                    child: Column(
                      children: [
                        Text('YOU BOTH EARN', style: GoogleFonts.poppins(color: Colors.white70, fontSize: 10, letterSpacing: 1.4, fontWeight: FontWeight.w700)),
                        const SizedBox(height: 5),
                        Text('250 Coins each', style: GoogleFonts.poppins(color: Colors.white, fontSize: 25, fontWeight: FontWeight.w800)),
                        Text('When your friend signs up with your code', textAlign: TextAlign.center,
                            style: GoogleFonts.poppins(color: Colors.white.withValues(alpha: 0.85), fontSize: 10.5)),
                      ],
                    ),
                  ),
                ],
              ),
            ),
            const SizedBox(height: 22),
            Text('Your referral code', style: GoogleFonts.poppins(fontSize: 17, fontWeight: FontWeight.w700, color: colors.onSurface)),
            const SizedBox(height: 5),
            Text('Share this code with a friend when they create an account.',
                style: GoogleFonts.poppins(fontSize: 11.5, height: 1.5, color: colors.onSurfaceVariant)),
            const SizedBox(height: 12),
            if (!_loadingCode && _referralCode.isEmpty && _loadError != null) ...[
              Container(
                padding: const EdgeInsets.all(12),
                decoration: BoxDecoration(
                  color: colors.errorContainer,
                  borderRadius: BorderRadius.circular(14),
                ),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      _loadError!,
                      style: GoogleFonts.poppins(
                        fontSize: 11,
                        color: colors.onErrorContainer,
                      ),
                    ),
                    const SizedBox(height: 8),
                    Align(
                      alignment: Alignment.centerRight,
                      child: TextButton.icon(
                        onPressed: _loadReferralCode,
                        icon: const Icon(Icons.refresh_rounded),
                        label: const Text('Try again'),
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(height: 10),
            ],
            Container(
              padding: const EdgeInsets.all(16),
              decoration: BoxDecoration(
                color: colors.surface,
                borderRadius: BorderRadius.circular(20),
                border: Border.all(color: colors.outline.withValues(alpha: 0.16)),
              ),
              child: Row(
                children: [
                  Container(
                    width: 45, height: 45,
                    decoration: BoxDecoration(color: colors.primary.withValues(alpha: 0.10), borderRadius: BorderRadius.circular(14)),
                    child: Icon(Icons.confirmation_number_rounded, color: colors.primary),
                  ),
                  const SizedBox(width: 12),
                  Expanded(
                    child: Text(code, style: GoogleFonts.poppins(fontSize: 18, letterSpacing: 1.1, fontWeight: FontWeight.w800, color: colors.onSurface)),
                  ),
                  IconButton(
                    tooltip: 'Copy referral code',
                    onPressed: _loadingCode || _referralCode.isEmpty ? null : () async {
                      await Clipboard.setData(ClipboardData(text: code));
                      if (context.mounted) {
                        ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Referral code copied')));
                      }
                    },
                    icon: Icon(Icons.copy_rounded, color: colors.primary),
                  ),
                ],
              ),
            ),
            const SizedBox(height: 22),
            Text('How it works', style: GoogleFonts.poppins(fontSize: 17, fontWeight: FontWeight.w700, color: colors.onSurface)),
            const SizedBox(height: 12),
            _StepCard(number: '01', icon: Icons.share_rounded, title: 'Share your code', description: 'Send your personal referral code to a friend.'),
            const SizedBox(height: 10),
            _StepCard(number: '02', icon: Icons.person_add_alt_1_rounded, title: 'Your friend signs up', description: 'They enter your referral code during registration.'),
            const SizedBox(height: 10),
            _StepCard(number: '03', icon: Icons.monetization_on_rounded, title: 'Earn 250 Coins each', description: 'Rewards should appear after the signup and referral are verified.'),
            const SizedBox(height: 16),
            Container(
              padding: const EdgeInsets.all(13),
              decoration: BoxDecoration(
                color: dark ? colors.surfaceContainerHighest.withValues(alpha: 0.5) : colors.surfaceContainerHighest.withValues(alpha: 0.65),
                borderRadius: BorderRadius.circular(16),
              ),
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Icon(Icons.info_outline_rounded, size: 19, color: colors.onSurfaceVariant),
                  const SizedBox(width: 9),
                  Expanded(child: Text(
                    'Your referral code is generated and stored by AiTradeX. When a new friend signs up with it, both accounts receive 250 Coins once.',
                    style: GoogleFonts.poppins(fontSize: 10.5, height: 1.45, color: colors.onSurfaceVariant),
                  )),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class _StepCard extends StatelessWidget {
  const _StepCard({required this.number, required this.icon, required this.title, required this.description});
  final String number;
  final IconData icon;
  final String title;
  final String description;

  @override
  Widget build(BuildContext context) {
    final ColorScheme colors = Theme.of(context).colorScheme;
    return Container(
      padding: const EdgeInsets.all(15),
      decoration: BoxDecoration(
        color: colors.surface,
        borderRadius: BorderRadius.circular(18),
        border: Border.all(color: colors.outline.withValues(alpha: 0.13)),
      ),
      child: Row(
        children: [
          Container(
            width: 45, height: 45,
            decoration: BoxDecoration(color: colors.primary.withValues(alpha: 0.10), borderRadius: BorderRadius.circular(14)),
            child: Icon(icon, color: colors.primary, size: 22),
          ),
          const SizedBox(width: 12),
          Expanded(child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(title, style: GoogleFonts.poppins(fontSize: 13, fontWeight: FontWeight.w700, color: colors.onSurface)),
              const SizedBox(height: 3),
              Text(description, style: GoogleFonts.poppins(fontSize: 10.5, height: 1.4, color: colors.onSurfaceVariant)),
            ],
          )),
          Text(number, style: GoogleFonts.poppins(fontSize: 10, fontWeight: FontWeight.w800, color: colors.primary.withValues(alpha: 0.75))),
        ],
      ),
    );
  }
}
